import {normalizeDocument,registerName} from '../core/registers.js?v=20261111-v15a';
import {configSection,round} from '../core/business.js?v=20261111-v15a';
export function registerChoices(ctx,type,query=''){
 if(!ctx.can(type,'view'))return [];
 const needle=registerName(query),document=normalizeDocument(query);
 return (ctx[type]||[]).filter(record=>record.active!==false&&(!needle||registerName(record.name+' '+(record.sku||'')+' '+(record.reference||'')).includes(needle)||(document&&normalizeDocument(record.document).includes(document)))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
}
export function productEntryValues(product,kind,quantity,unitPrice){
 const count=Number(quantity),price=Number(unitPrice??(kind==='income'?product.retail:product.cost));
 if(!Number.isFinite(count)||count<=0||count>1000000||!Number.isFinite(price)||price<0||price>9999999999)throw Error('Informe quantidade e preço válidos.');
 const amount=round(count*price);if(amount<=0||amount>9999999999)throw Error('O total do lançamento deve ser maior que zero e estar dentro do limite.');
 return {description:(product.name+' · '+count.toLocaleString('pt-BR')+' unidade(s)').slice(0,1000),amount,quantity:count,unit_price:price,product_id:product.id};
}
export function install(ctx){
 const names={clients:['cliente','clientes'],suppliers:['fornecedor','fornecedores'],products:['produto','produtos']};
 function createRegister(type,onSaved,prefill={},context='lançamento'){
  if(type==='suppliers'){const editor=ctx.supplierDialog(null,onSaved);if(editor)ctx.fillContact(editor.form,prefill)}else ctx.quickRecordDialog(type,onSaved,prefill,context);
 }
 function registerPickerDialog(type,onPick,{context='lançamento'}={}){
  if(!ctx.can(type,'view'))return ctx.toast('Seu acesso não permite consultar esse cadastro.');
  const label=names[type],d=ctx.modal('Selecionar '+label[0],`<label class="field">Buscar por nome, ${type==='products'?'código ou referência':'CPF ou CNPJ'}<input type="search" data-register-search autocomplete="off"></label><div data-register-results></div><div class="form-actions">${ctx.can(type,'create')?'<button type="button" class="primary" data-register-new>Cadastrar '+label[0]+'</button>':''}<button type="button" class="secondary" data-close>Fechar</button></div>`,{wide:true});
  const pick=record=>{d.close();onPick(record)},search=d.querySelector('[data-register-search]');
  function draw(){const rows=registerChoices(ctx,type,search.value);d.querySelector('[data-register-results]').innerHTML=rows.length?`<p class="helper muted">${rows.length} ${label[1]} encontrado(s)${rows.length>40?' · refine a busca para ver os demais':''}.</p><div class="register-picker-list">${rows.slice(0,40).map(record=>`<button type="button" class="secondary register-picker-row" data-pick-register="${ctx.esc(record.id)}"><strong>${ctx.esc(record.name)}</strong><small>${ctx.esc(type==='products'?[record.sku,record.reference].filter(Boolean).join(' · '):record.document||record.phone||'Sem documento informado')}</small></button>`).join('')}</div>`:'<p class="muted">Nenhum cadastro encontrado. Você pode cadastrar sem sair do lançamento.</p>';d.querySelectorAll('[data-pick-register]').forEach(button=>button.onclick=()=>pick(rows.find(record=>record.id===button.dataset.pickRegister)))}
  search.oninput=draw;d.querySelector('[data-register-new]')?.addEventListener('click',()=>createRegister(type,pick,{name:search.value},context));draw();return d;
 }
 function mountPartyField(form,{getType,onPick=()=>{},context='lançamento'}={}){
  const input=form.elements.namedItem('party');if(!input)return;
  const controls=document.createElement('div');controls.className='register-field-controls';controls.innerHTML='<div class="register-field-buttons"><button type="button" class="secondary small" data-party-select></button><button type="button" class="secondary small" data-party-create></button><button type="button" class="secondary small" data-party-document>Consultar CPF/CNPJ</button></div><p class="helper muted" data-party-status></p>';
  input.closest('label').after(controls);let chosen=null;
  const choose=record=>{chosen={...record,type:getType()};input.value=record.name;controls.querySelector('[data-party-status]').textContent=[record.name,record.document,record.phone,record.email].filter(Boolean).join(' · ');onPick(chosen)};
  function update(){const type=getType(),label=names[type][0],listId='party-options-'+crypto.randomUUID();chosen=null;onPick(null);const fieldLabel=input.closest('label');let caption=fieldLabel.querySelector('[data-party-caption]');if(!caption){caption=document.createElement('span');caption.dataset.partyCaption='';if(fieldLabel.firstChild?.nodeType===3)fieldLabel.firstChild.remove();fieldLabel.prepend(caption)}caption.textContent=label==='cliente'?'Cliente':'Fornecedor';input.setAttribute('aria-label',label==='cliente'?'Cliente':'Fornecedor');input.placeholder='Digite o nome ou escolha no cadastro';input.setAttribute('list',listId);controls.querySelector('datalist')?.remove();const list=document.createElement('datalist');list.id=listId;list.innerHTML=registerChoices(ctx,type).map(record=>`<option value="${ctx.esc(record.name)}">${ctx.esc(record.document||record.phone||'')}</option>`).join('');if(form.elements.namedItem('class')?.value==='equity'||form.elements.namedItem('category')?.value==='Pró-labore')list.innerHTML+=configSection(ctx.settings,'finance').partners.map(name=>`<option value="${ctx.esc(name)}">Sócio</option>`).join('');controls.append(list);controls.querySelector('[data-party-select]').textContent='Selecionar '+label;controls.querySelector('[data-party-select]').hidden=!ctx.can(type,'view');controls.querySelector('[data-party-create]').textContent='Cadastrar '+label;controls.querySelector('[data-party-create]').hidden=!ctx.can(type,'create');controls.querySelector('[data-party-status]').textContent=type==='clients'?'Entradas: selecione um cliente da base da Avelon.':'Saídas: selecione um fornecedor da base da Avelon. Para pró-labore, informe o sócio.';const matches=registerChoices(ctx,type).filter(record=>registerName(record.name)===registerName(input.value));if(matches.length===1)choose(matches[0]);}
  controls.querySelector('[data-party-select]').onclick=()=>registerPickerDialog(getType(),choose,{context});controls.querySelector('[data-party-create]').onclick=()=>createRegister(getType(),record=>{update();choose(record)},{name:input.value},context);controls.querySelector('[data-party-document]').onclick=()=>ctx.partyLookupDialog(getType(),record=>{update();choose(record)},context);
  input.addEventListener('input',()=>{const matches=registerChoices(ctx,getType()).filter(record=>registerName(record.name)===registerName(input.value));if(matches.length===1)choose(matches[0]);else{chosen=null;onPick(null);controls.querySelector('[data-party-status]').textContent=matches.length>1?'Há nomes iguais. Use Selecionar para identificar pelo documento.':'Nome livre: selecione ou cadastre para vincular ao cadastro da Avelon.'}});
  for(const name of ['kind','class','category'])form.elements.namedItem(name)?.addEventListener('change',update);update();return {update,get selected(){return chosen}};
 }
 function productEntryDialog(kind,onApply){
  registerPickerDialog('products',product=>{const suggested=kind==='income'?Number(product.retail):Number(product.cost),d=ctx.modal('Usar produto no lançamento',`<form><p><strong>${ctx.esc(product.name)}</strong> · ${ctx.esc(product.sku||'')}</p><div class="grid2">${ctx.field('Quantidade','quantity','number',1,'required min="0.001" max="1000000" step="0.001"')}${ctx.field(kind==='income'?'Preço unitário de venda (R$)':'Custo unitário (R$)','unit_price','number',suggested,'required min="0" max="9999999999" step="0.01"')}</div><p data-product-total></p><p class="note">Aplicar preenche a descrição e o valor deste lançamento. O preço do cadastro não muda e nenhuma movimentação de estoque é gerada.</p><p class="error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-close>Cancelar</button><button class="primary" type="submit">Aplicar ao lançamento</button></div></form>`);const form=d.querySelector('form');const calculate=()=>{try{const values=productEntryValues(product,kind,form.elements.quantity.value,form.elements.unit_price.value);d.querySelector('[data-product-total]').textContent='Total: '+ctx.money(values.amount);return values}catch(error){d.querySelector('[data-product-total]').textContent=error.message;return null}};form.oninput=calculate;form.onsubmit=e=>{e.preventDefault();const values=calculate();if(!values)return;d.close();onApply(values,product)};calculate()});
 }
 Object.assign(ctx,{registerPickerDialog,createRegister,mountPartyField,productEntryDialog});
}
